#!/usr/bin/env node
// hs86e-ui-polish-release.mjs
// HS86E UI polish release - create-event fail-soft, mobile header scale,
// floating + overlap fix, scroll clearance, PWA prompt relocation, gold top progress bar.
// Pure ASCII; file payloads are base64 (byte-exact). Idempotent - safe to re-run.
//   node hs86e-ui-polish-release.mjs [path-to-repo-root]
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";

const startDir = resolve(process.argv[2] || ".");
let APP = null;
for (const candidate of [startDir, join(startDir, "hs86e-tickets")]) {
  if (existsSync(join(candidate, "package.json"))) { APP = candidate; break; }
}
if (!APP) {
  console.log(`[FAILED] Cannot locate hs86e-tickets app root at '${startDir}' or '${join(startDir, "hs86e-tickets")}'.`);
  process.exit(1);
}
console.log("App root:", APP);

function writeB64(rel, b64) {
  const target = join(APP, rel);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, Buffer.from(b64, "base64"));
  console.log("[write]", rel);
}

